    54→        public bool IsPersisted
    55→        {
    56→            get => (Volatile.Read(ref _blockAndFlags) & _persistedMask) != 0;
    57→            set
    58→            {
    59→                byte previousValue = Volatile.Read(ref _blockAndFlags);
    60→                byte currentValue;
    61→                do
    62→                {
    63→                    currentValue = previousValue;
    64→                    byte newValue = (byte)(value ? (currentValue | _persistedMask) : (currentValue & ~_persistedMask));
    65→                    previousValue = Interlocked.CompareExchange(ref _blockAndFlags, newValue, currentValue);
    66→                } while (previousValue != currentValue);
    67→            }
