   330→        public void ResolveNode(ITrieNodeResolver tree, in TreePath path, ReadFlags readFlags = ReadFlags.None,
   331→            ICappedArrayPool? bufferPool = null)
   332→        {
   333→            if (NodeType != NodeType.Unknown) return;
   334→
   335→            try
   336→            {
   337→                ResolveUnknownNode(tree, path, readFlags, bufferPool);
   338→            }
   339→            catch (RlpException rlpException)
   340→            {
   341→                ThrowDecodingError(rlpException, path);
