   352→        /// <summary>
   353→        /// Highly optimized
   354→        /// </summary>
   355→        internal void ResolveUnknownNode(ITrieNodeResolver tree, in TreePath path, ReadFlags readFlags = ReadFlags.None,
   356→            ICappedArrayPool? bufferPool = null)
   357→        {
   358→            SpanSource rlp = _rlp;
   359→            if (rlp.IsNull)
   360→            {
   361→                Hash256 keccak = Keccak;
   362→                if (keccak is null)
   363→                {
   364→                    ThrowMissingKeccak();
   365→                }
   366→
   367→                byte[]? fullRlp = tree.LoadRlp(path, keccak, readFlags);
   368→
   369→                if (fullRlp == null)
   370→                {
   371→                    ThrowNullRlp();
   372→                }
   373→
   374→                _rlp = rlp = new SpanSource(fullRlp);
   375→                IsPersisted = true;
   376→            }
   377→
   378→            if (!DecodeRlp(new ValueRlpStream(rlp), bufferPool, out int numberOfItems))
   379→            {
   380→                ThrowUnexpectedNumberOfItems(numberOfItems, path);
   381→            }
