   485→        public void ResolveKey(ITrieNodeResolver tree, ref TreePath path,
   486→            ICappedArrayPool? bufferPool = null, bool canBeParallel = true)
   487→        {
   488→            if (Keccak is not null)
   489→            {
   490→                // please note it is totally fine to leave the RLP null here
   491→                // this node will simply act as a ref only node (a ref to some node with unresolved data in the DB)
   492→                return;
   493→            }
   494→
   495→            Keccak = GenerateKey(tree, ref path, bufferPool, canBeParallel);
   496→        }
