   549→        public Hash256? GetChildHash(int i)
   550→        {
   551→            SpanSource rlp = _rlp;
   552→            if (rlp.IsNull)
   553→            {
   554→                return null;
   555→            }
   556→
   557→            ValueRlpStream rlpStream = new(rlp);
   558→            SeekChild(ref rlpStream, i);
   559→            (int _, int length) = rlpStream.PeekPrefixAndContentLength();
   560→            return length == 32 ? rlpStream.DecodeKeccak() : null;
