   583→        public bool IsChildNull(int i)
   584→        {
   585→            if (!IsBranch)
   586→            {
   587→                ThrowNotABranch();
   588→            }
   589→
   590→            SpanSource rlp = _rlp;
   591→            ref var data = ref _nodeData[i];
   592→            if (rlp.IsNotNull && data is null)
   593→            {
   594→                ValueRlpStream rlpStream = new(rlp);
   595→                SeekChild(ref rlpStream, i);
   596→                return rlpStream.PeekNextRlpLength() == 1;
   597→            }
   598→
   599→            return data is null || ReferenceEquals(data, _nullNode);
