   699→            // pruning trick so we never store long persisted paths
   700→            // Dont unresolve node of path length <= 4. there should be a relatively small number of these, enough to fit
   701→            // in RAM, but they are hit quite a lot, and don't have very good data locality.
   702→            // That said, in practice, it does nothing notable, except for significantly improving benchmark score.
   703→            if (child?.IsPersisted == true && childPath.Length > 4 && childPath.Length % 2 == 0)
   704→            {
   705→                UnresolveChild(childIndex);
   706→            }
   707→
   708→            return child;
