     9→using System.Threading;
    10→using Nethermind.Core.Buffers;
    11→using Nethermind.Core.Cpu;
    12→using Nethermind.Core.Crypto;
    13→using Nethermind.Core.Threading;
    14→using Nethermind.Serialization.Rlp;
    15→using Nethermind.Trie.Pruning;
    16→
    17→[assembly: InternalsVisibleTo("Ethereum.Trie.Test")]
    18→[assembly: InternalsVisibleTo("Nethermind.Blockchain.Test")]
    19→[assembly: InternalsVisibleTo("Nethermind.Trie.Test")]
    20→
    21→namespace Nethermind.Trie
    22→{
    23→    public partial class TrieNode
    24→    {
    25→        // Used to create the nibble key from bytes, and threshold before using ArrayPool for the key
    26→        private const int StackallocByteThreshold = 384;
    27→
    28→        private class TrieNodeDecoder
    29→        {
    30→            [SkipLocalsInit]
    31→            public static SpanSource EncodeExtension(TrieNode item, ITrieNodeResolver tree, ref TreePath path, ICappedArrayPool? bufferPool)
    32→            {
    33→                Metrics.TreeNodeRlpEncodings++;
    34→
    35→                Debug.Assert(item.NodeType == NodeType.Extension,
    36→                    $"Node passed to {nameof(EncodeExtension)} is {item.NodeType}");
    37→                Debug.Assert(item.Key is not null,
    38→                    "Extension key is null when encoding");
    39→
    40→                byte[] hexPrefix = item.Key;
    41→                int hexLength = HexPrefix.ByteLength(hexPrefix);
    42→                byte[]? rentedBuffer = hexLength > StackallocByteThreshold
    43→                    ? ArrayPool<byte>.Shared.Rent(hexLength)
    44→                    : null;
    45→
    46→                Span<byte> keyBytes = (rentedBuffer is null
    47→                    ? stackalloc byte[StackallocByteThreshold]
    48→                    : rentedBuffer)[..hexLength];
    49→
    50→                HexPrefix.CopyToSpan(hexPrefix, isLeaf: false, keyBytes);
    51→
    52→                int previousLength = item.AppendChildPath(ref path, 0);
    53→                TrieNode nodeRef = item.GetChildWithChildPath(tree, ref path, 0);
    54→                Debug.Assert(nodeRef is not null,
    55→                    "Extension child is null when encoding.");
    56→
    57→                nodeRef.ResolveKey(tree, ref path, bufferPool: bufferPool);
    58→                path.TruncateMut(previousLength);
    59→
    60→                int contentLength = Rlp.LengthOf(keyBytes) + (nodeRef.Keccak is null ? nodeRef.FullRlp.Length : Rlp.LengthOfKeccakRlp);
    61→                int totalLength = Rlp.LengthOfSequence(contentLength);
    62→
    63→                SpanSource data = bufferPool.SafeRentBuffer(totalLength);
    64→                Span<byte> destination = data.Span;
    65→                int position = Rlp.StartSequence(destination, 0, contentLength);
    66→                position = Rlp.Encode(destination, position, keyBytes);
    67→
    68→                if (rentedBuffer is not null)
    69→                {
    70→                    ArrayPool<byte>.Shared.Return(rentedBuffer);
    71→                }
    72→                if (nodeRef.Keccak is null)
    73→                {
    74→                    // I think it can only happen if we have a short extension to a branch with a short extension as the only child?
    75→                    // so |
    76→                    // so |
    77→                    // so E - - - - - - - - - - - - - - -
    78→                    // so |
    79→                    // so |
    80→                    nodeRef.FullRlp.Span.CopyTo(destination.Slice(position));
    81→                }
    82→                else
    83→                {
    84→                    Rlp.Encode(destination, position, nodeRef.Keccak);
    85→                }
    86→
    87→                return data;
    88→            }
    89→
    90→            [SkipLocalsInit]
    91→            public static SpanSource EncodeLeaf(TrieNode node, ICappedArrayPool? pool)
    92→            {
    93→                Metrics.TreeNodeRlpEncodings++;
    94→
    95→                if (node.Key is null)
    96→                {
    97→                    ThrowNullKey(node);
    98→                }
    99→
   100→                byte[] hexPrefix = node.Key;
   101→                int hexLength = HexPrefix.ByteLength(hexPrefix);
   102→                byte[]? rentedBuffer = hexLength > StackallocByteThreshold
   103→                    ? ArrayPool<byte>.Shared.Rent(hexLength)
   104→                    : null;
   105→
   106→                Span<byte> keyBytes = (rentedBuffer is null
   107→                    ? stackalloc byte[StackallocByteThreshold]
   108→                    : rentedBuffer)[..hexLength];
   109→
   110→                HexPrefix.CopyToSpan(hexPrefix, isLeaf: true, keyBytes);
   111→                int contentLength = Rlp.LengthOf(keyBytes) + Rlp.LengthOf(node.Value.Span);
   112→                int totalLength = Rlp.LengthOfSequence(contentLength);
   113→
   114→                SpanSource data = pool.SafeRentBuffer(totalLength);
   115→                Span<byte> destination = data.Span;
   116→                int position = Rlp.StartSequence(destination, 0, contentLength);
   117→                position = Rlp.Encode(destination, position, keyBytes);
   118→
   119→                if (rentedBuffer is not null)
   120→                {
   121→                    ArrayPool<byte>.Shared.Return(rentedBuffer);
   122→                }
   123→
   124→                Rlp.Encode(destination, position, node.Value.Span);
   125→
   126→                return data;
   127→            }
   128→
   129→            [DoesNotReturn, StackTraceHidden]
   130→            private static void ThrowNullKey(TrieNode node)
   131→            {
   132→                throw new TrieException($"Hex prefix of a leaf node is null at node {node.Keccak}");
   133→            }
   134→
   135→            public static SpanSource RlpEncodeBranch(TrieNode item, ITrieNodeResolver tree, ref TreePath path, ICappedArrayPool? pool, bool canBeParallel)
   136→            {
   137→                Metrics.TreeNodeRlpEncodings++;
   138→
   139→                const int valueRlpLength = 1;
   140→                int contentLength = valueRlpLength + (UseParallel(canBeParallel) ? GetChildrenRlpLengthForBranchParallel(tree, ref path, item, pool) : GetChildrenRlpLengthForBranch(tree, ref path, item, pool));
   141→                int sequenceLength = Rlp.LengthOfSequence(contentLength);
   142→                SpanSource result = pool.SafeRentBuffer(sequenceLength);
   143→                Span<byte> resultSpan = result.Span;
   144→                int position = Rlp.StartSequence(resultSpan, 0, contentLength);
   145→                WriteChildrenRlpBranch(tree, ref path, item, resultSpan.Slice(position, contentLength - valueRlpLength), pool);
   146→                position = sequenceLength - valueRlpLength;
   147→                resultSpan[position] = 128;
   148→
   149→                return result;
   150→
   151→                static bool UseParallel(bool canBeParallel) => Environment.ProcessorCount > 1 && canBeParallel;
   152→            }
   153→
   154→            private static int GetChildrenRlpLengthForBranch(ITrieNodeResolver tree, ref TreePath path, TrieNode item, ICappedArrayPool? bufferPool)
   155→            {
   156→                // Tail call optimized.
   157→                return item.HasRlp
   158→                    ? GetChildrenRlpLengthForBranchRlp(tree, ref path, item, bufferPool)
   159→                    : GetChildrenRlpLengthForBranchNonRlp(tree, ref path, item, bufferPool);
   160→            }
   161→
   162→            private static int GetChildrenRlpLengthForBranchParallel(ITrieNodeResolver tree, ref TreePath path, TrieNode item, ICappedArrayPool? bufferPool)
   163→            {
   164→                // Tail call optimized.
   165→                return item.HasRlp
   166→                    ? GetChildrenRlpLengthForBranchRlpParallel(tree, path, item, bufferPool)
   167→                    : GetChildrenRlpLengthForBranchNonRlpParallel(tree, path, item, bufferPool);
   168→            }
   169→
   170→            private static int GetChildrenRlpLengthForBranchNonRlpParallel(ITrieNodeResolver tree, TreePath rootPath, TrieNode item, ICappedArrayPool bufferPool)
   171→            {
   172→                int totalLength = 0;
   173→                ParallelUnbalancedWork.For(0, BranchesCount, RuntimeInformation.ParallelOptionsPhysicalCoresUpTo16,
   174→                    (local: 0, item, tree, bufferPool, rootPath),
   175→                    static (i, state) =>
   176→                    {
   177→                        object? data = state.item._nodeData[i];
   178→                        if (ReferenceEquals(data, _nullNode) || data is null)
   179→                        {
   180→                            state.local++;
   181→                        }
   182→                        else if (data is Hash256)
   183→                        {
   184→                            state.local += Rlp.LengthOfKeccakRlp;
   185→                        }
   186→                        else
   187→                        {
   188→                            TreePath path = state.rootPath;
   189→                            path.AppendMut(i);
   190→                            TrieNode childNode = Unsafe.As<TrieNode>(data);
   191→                            childNode.ResolveKey(state.tree, ref path, bufferPool: state.bufferPool);
   192→                            state.local += childNode.Keccak is null ? childNode.FullRlp.Length : Rlp.LengthOfKeccakRlp;
   193→                        }
   194→
   195→                        return state;
   196→                    },
   197→                    state =>
   198→                    {
   199→                        Interlocked.Add(ref totalLength, state.local);
   200→                    });
   201→
   202→                return totalLength;
   203→            }
   204→
   205→            private static int GetChildrenRlpLengthForBranchNonRlp(ITrieNodeResolver tree, ref TreePath path, TrieNode item, ICappedArrayPool bufferPool)
   206→            {
   207→                int totalLength = 0;
   208→                for (int i = 0; i < BranchesCount; i++)
   209→                {
   210→                    object? data = item._nodeData[i];
   211→                    if (ReferenceEquals(data, _nullNode) || data is null)
   212→                    {
   213→                        totalLength++;
   214→                    }
   215→                    else if (data is Hash256)
   216→                    {
   217→                        totalLength += Rlp.LengthOfKeccakRlp;
   218→                    }
   219→                    else
   220→                    {
   221→                        path.AppendMut(i);
   222→                        TrieNode childNode = Unsafe.As<TrieNode>(data);
   223→                        childNode.ResolveKey(tree, ref path, bufferPool: bufferPool);
   224→                        path.TruncateOne();
   225→                        totalLength += childNode.Keccak is null ? childNode.FullRlp.Length : Rlp.LengthOfKeccakRlp;
   226→                    }
   227→                }
   228→                return totalLength;
   229→            }
   230→
   231→            private static int GetChildrenRlpLengthForBranchRlpParallel(ITrieNodeResolver tree, TreePath rootPath, TrieNode item, ICappedArrayPool? bufferPool)
   232→            {
   233→                int totalLength = 0;
   234→                ParallelUnbalancedWork.For(0, BranchesCount, RuntimeInformation.ParallelOptionsPhysicalCoresUpTo16,
   235→                    (local: 0, item, tree, bufferPool, rootPath),
   236→                    static (i, state) =>
   237→                    {
   238→                        ValueRlpStream rlpStream = state.item.RlpStream;
   239→                        state.item.SeekChild(ref rlpStream, i);
   240→                        object? data = state.item._nodeData[i];
   241→                        if (data is null)
   242→                        {
   243→                            state.local += rlpStream.PeekNextRlpLength();
   244→                        }
   245→                        else if (ReferenceEquals(data, _nullNode))
   246→                        {
   247→                            state.local++;
   248→                        }
   249→                        else if (data is Hash256)
   250→                        {
   251→                            state.local += Rlp.LengthOfKeccakRlp;
   252→                        }
   253→                        else
   254→                        {
   255→                            TreePath path = state.rootPath;
